/// Calculates the n-th Fibonacci number.
///
/// # Examples
///
/// ```
/// assert_eq!(fib(0), 0);
/// assert_eq!(fib(1), 1);
/// assert_eq!(fib(2), 1);
/// assert_eq!(fib(3), 2);
/// assert_eq!(fib(4), 3);
/// assert_eq!(fib(5), 5);
/// assert_eq!(fib(6), 8);
/// assert_eq!(fib(7), 13);
/// assert_eq!(fib(8), 21);
/// assert_eq!(fib(9), 34);
/// ```
fn fib(n: u32) -> u64 {
    match n {
        0 => 0,
        1 => 1,
        _ => {
            let (a, b) = (0, 1);
            for _ in 2..=n {
                let next = a + b;
                a = b;
                b = next;
            }
            next
        }
    }
}

// Function to check the correctness of the fib function
fn check_fib() {
    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(2), 1);
    assert_eq!(fib(3), 2);
    assert_eq!(fib(4), 3);
    assert_eq!(fib(5), 5);
    assert_eq!(fib(6), 8);
    assert_eq!(fib(7), 13);
    assert_eq!(fib(8), 21);
    assert_eq!(fib(9), 34);
    println!("All tests passed successfully!");
}

