/// Checks if a string is a palindrome, ignoring case and non-letter/digit characters.
///
/// # Examples
///
/// ```
/// assert_eq!(is_palindrome("A man, a plan, a canal, Panama"), true);
/// assert_eq!(is_palindrome("No lemon, no melon"), true);
/// assert_eq!(is_palindrome("Hello, World!"), false);
/// assert_eq!(is_palindrome("12345"), false);
/// ```
fn is_palindrome(s: &str) -> bool {
    let cleaned_s: String = s.chars()
        .filter(|c| c.is_alphanumeric() && c.is_ascii_lowercase())
        .collect();
    cleaned_s == cleaned_s.chars().rev().collect()
}

