/// Encodes a string into run-length encoding.
///
/// # Examples
///
/// ```
/// assert_eq!(rle("aaabcc"), "3a1b2c");
/// assert_eq!(rle(""), "");
/// ```
fn rle(input: &str) -> String {
    if input.is_empty() {
        return String::new();
    }

    let mut encoded = String::new();
    let mut count = 1;

    for (i, c) in input.chars().enumerate() {
        if i == 0 || c == input[i - 1] {
            count += 1;
        } else {
            encoded.push_str(&format!("{}{}", count, c));
            count = 1;
        }
    }

    encoded.push_str(&format!("{}{}", count, c));
    encoded
}

// Check function to verify the correctness of the `rle` function.
fn check() {
    assert_eq!(rle("aaabcc"), "3a1b2c");
    assert_eq!(rle(""), "");
    assert_eq!(rle("aabbcc"), "3a2b2c");
    assert_eq!(rle("abc"), "3a1b2c");
    assert_eq!(rle("aabbccdd"), "3a2b2c3d");
    println!("All tests passed successfully!");
}

