/// Calculate the greatest common divisor (GCD) of two numbers `a` and `b`.
/// The GCD is the largest positive integer that divides both `a` and `b`.
/// If either `a` or `b` is zero, the GCD is the absolute value of the other number.
///
/// # Examples
///
/// ```
/// assert_eq!(gcd(48, 18), 6);
/// assert_eq!(gcd(0, 10), 10);
/// assert_eq!(gcd(21, 6), 7);
/// ```
fn gcd(a: u64, b: u64) -> u64 {
    if a == 0 {
        return b.abs();
    }
    if b == 0 {
        return a.abs();
    }
    while b != 0 {
        let temp = b;
        b = a % b;
        a = temp;
    }
    a
}

// Function to check the correctness of the gcd function
fn check_gcd() {
    assert_eq!(gcd(48, 18), 6);
    assert_eq!(gcd(0, 10), 10);
    assert_eq!(gcd(21, 6), 7);
    println!("All tests passed successfully!");
}

