/// Reverses the words in a given string and returns them as a single string.
/// Words are separated by spaces.
///
/// # Examples
///
/// ```
/// assert_eq!(reverse_words(String::from("hello world")), String::from("dlrow olleh"));
/// assert_eq!(reverse_words(String::from("rust programming")), String::from("gnimmargorp tsuhrn"));
/// ```
fn reverse_words(s: &str) -> String {
    s.split_whitespace().rev().collect::<Vec<String>>().join(" ")
}

