/// Finds the maximum sum of a contiguous subarray in a given slice of integers.
///
/// # Examples
///
/// ```
/// assert_eq!(max_subarray(&[1, 2, 3, 4]), 10);
/// assert_eq!(max_subarray(&[-1, -2, -3]), -6);
/// assert_eq!(max_subarray(&[]), 0);
/// ```
fn max_subarray(v: &[i64]) -> i64 {
    if v.is_empty() {
        return 0;
    }

    let mut max_so_far = v[0];
    let mut max_ending_here = v[0];

    for &num in v.iter().skip(1) {
        max_ending_here = max(num, max_ending_here + num);
        max_so_far = max(max_so_far, max_ending_here);
    }

    max_so_far
}

// Check function to verify the correctness of the `max_subarray` function.
fn check() {
    assert_eq!(max_subarray(&[1, 2, 3, 4]), 10);
    assert_eq!(max_subarray(&[-1, -2, -3]), -6);
    assert_eq!(max_subarray(&[]), 0);
    println!("All tests passed successfully.");
}

