/// Finds the index of the target in the sorted slice v using binary search.
/// If the target is not found, returns None.
///
/// # Examples
///
/// ```
/// assert_eq!(find(&[1, 2, 3, 4, 5], 3), Some(2));
/// assert_eq!(find(&[1, 2, 3, 4, 5], 6), None);
/// ```
fn find(v: &[i32], target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = v.len() - 1;

    while left <= right {
        let mid = left + (right - left) / 2;

        if v[mid] == target {
            return Some(mid);
        } else if v[mid] < target {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    None
}

