/// Converts a Roman numeral to a number.
/// Returns None if the input is empty or contains invalid characters.
///
/// # Examples
///
/// ```
/// assert_eq!(from_roman("III"), Some(3));
/// assert_eq!(from_roman("IV"), Some(4));
/// assert_eq!(from_roman("IX"), Some(9));
/// assert_eq!(from_roman("LVIII"), Some(58));
/// assert_eq!(from_roman("XLVI"), Some(46));
/// assert_eq!(from_roman("MCMXC"), Some(1999));
/// assert_eq!(from_roman("CM"), Some(1000));
/// assert_eq!(from_roman("D"), Some(50));
/// assert_eq!(from_roman("CD"), Some(400));
/// assert_eq!(from_roman("C"), Some(100));
/// assert_eq!(from_roman("XC"), Some(90));
/// assert_eq!(from_roman("L"), Some(50));
/// assert_eq!(from_roman("XL"), Some(40));
/// assert_eq!(from_roman("X"), Some(10));
/// assert_eq!(from_roman("IX"), Some(9));
/// assert_eq!(from_roman("V"), Some(5));
/// assert_eq!(from_roman("IV"), Some(4));
/// assert_eq!(from_roman("I"), Some(1));
/// ```
fn from_roman(s: &str) -> Option<u32> {
    if s.is_empty() {
        return None;
    }

    let mut total = 0;
    let mut i = 0;

    while i < s.len() {
        let char = s.chars().nth(i).unwrap();
        match char {
            'I' => total += 1,
            'V' => total += 5,
            'X' => total += 10,
            'L' => total += 50,
            'C' => total += 100,
            'D' => total += 500,
            'M' => total += 1000,
            _ => return None, // Invalid character
        }

        i += 1;
    }

    Some(total)
}

// Check function to verify the correctness of the `from_roman` function.
fn check() {
