/// Encrypts a given string using Caesar cipher with a specified shift.
///
/// # Examples
///
/// ```
/// assert_eq!(caesar("hello", 3), "lipps");
/// assert_eq!(caesar("world", 5), "asvph");
/// ```
fn caesar(s: &str, shift: u8) -> String {
    let mut encrypted = String::new();
    for c in s.chars() {
        if c.is_ascii_alphabetic() {
            let base = if c.is_uppercase() { 65 } else { 97 };
            let offset = (c as u8 - base + shift) % 26 + base;
            encrypted.push(char::from(offset));
        } else {
            encrypted.push(c);
        }
    }
    encrypted
}

