/// Deduplicates consecutive repeated values in a vector.
///
/// # Examples
///
/// ```
/// assert_eq!(dedup(vec![1, 2, 3, 4, 5, 6, 7, 8, 9]), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);
/// assert_eq!(dedup(vec![1, 2, 2, 3, 4, 5, 6, 7, 8, 9]), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);
/// assert_eq!(dedup(vec![1, 2, 3, 4, 5, 6, 7, 8, 9]), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);
/// ```
fn dedup(v: &[i32]) -> Vec<i32> {
    let mut result = Vec::new();
    let mut current_value = v[0];

    for &value in v.iter() {
        if value == current_value {
            current_value += 1;
        } else {
            result.push(current_value);
            current_value = value;
        }
    }

    result.push(current_value); // Add the last value if it's not a duplicate

    result
}

