/// Merges two sorted slices into one sorted vector.
///
/// # Examples
///
/// ```
/// assert_eq!(merge_sorted(&[1, 2, 3], &[4, 5, 6]), &[1, 2, 3, 4, 5, 6]);
/// ```
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut merged = Vec::new();
    let mut i = 0;
    let mut j = 0;

    while i < a.len() && j < b.len() {
        if a[i] < b[j] {
            merged.push(a[i]);
            i += 1;
        } else {
            merged.push(b[j]);
            j += 1;
        }
    }

    while i < a.len() {
        merged.push(a[i]);
        i += 1;
    }

    while j < b.len() {
        merged.push(b[j]);
        j += 1;
    }

    merged
}

// Check function to verify the correctness of the `merge_sorted` function.
