    assert_eq!(merge_sorted(&[1, 2, 3], &[4, 5, 6]), &[1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[5, 3, 8, 1], &[2, 4, 6, 9]), &[2, 3, 4, 5, 6, 7, 8, 9]);
    assert_eq!(merge_sorted(&[], &[1]), &[1]);
    assert_eq!(merge_sorted(&[1], &[]), &[1]);
    println!("All tests passed successfully!");
}

