/// Determines if a given year is a leap year.
///
/// A leap year is divisible by 4, except for years that are divisible by 100,
/// unless they are also divisible by 400.
///
/// # Examples
///
/// ```
/// assert_eq!(is_leap_year(2024), true);
/// assert_eq!(is_leap_year(1900), true);
/// assert_eq!(is_leap_year(2001), false);
/// assert_eq!(is_leap_year(1901), false);
/// ```
fn is_leap_year(year: u32) -> bool {
    if year % 400 == 0 {
        return true;
    }
    if year % 100 == 0 {
        return false;
    }
    year % 4 == 0
}

