/// Finds the second largest distinct value in a vector of integers.
/// Returns None if there are fewer than two distinct values.
///
/// # Examples
///
/// ```
/// assert_eq!(second_largest(vec![4, 5, 6, 7, 8]), Some(7));
/// assert_eq!(second_largest(vec![10, 20, 30, 40, 50]), Some(40));
/// assert_eq!(second_largest(vec![1, 2, 3]), None);
/// ```
fn second_largest(v: &[i32]) -> Option<i32> {
    let mut distinct_values: HashSet<i32> = v.iter().collect();
    let mut distinct_values_vec: Vec<i32> = distinct_values.into_iter().collect();
    distinct_values_vec.sort_unstable_by(|a, b| b.cmp(a));

    if distinct_values_vec.len() < 2 {
        None
    } else {
        Some(distinct_values_vec[1])
    }
}

// Check function to verify the correctness of the generated function.
fn check() {
    assert_eq!(second_largest(vec![4, 5, 6, 7, 8]), Some(7));
    assert_eq!(second_largest(vec![10, 20, 30, 40, 50]), Some(40));
    assert_eq!(second_largest(vec![1, 2, 3]), None);
    assert_eq!(second_largest(vec![10, 20, 30, 40, 50, 60]), Some(50));
    println!("All tests passed successfully.");
}

