use std::collections::HashMap;

/// Parses a string containing key-value pairs separated by semicolons into a map.
/// Pairs are separated by ";", and each pair is "key=value".
/// Pairs without "=" are ignored.
///
/// # Examples
///
/// ```
/// assert_eq!(parse_kv("a=1;b=two"), HashMap::from([("a", "1"), ("b", "two")]));
/// assert_eq!(parse_kv("key1=value2;key3=value4"), HashMap::from([("key1", "value2"), ("key3", "value4")]));
/// ```
fn parse_kv(s: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();
    let mut current_pair = String::new();

    for c in s.chars() {
        if c == ';' {
            if current_pair.is_empty() {
                continue;
            }
            let key = current_pair.trim();
            current_pair.clear();
            map.insert(key, current_pair);
        } else {
            current_pair.push(c);
        }
    }

    map
}

